{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "Accept the 20% general cap **only** once the carve-outs are fixed."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PARTIAL",
      "evidence": "The de minimis and a ~1% basket are acceptable."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Push for **24 months** minimum"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title, capacity and tax warranties capped at **100% of price**"
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "A fraud carve-out from every cap and time limit is non-negotiable and standard."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket \"everything in the data room\" general disclosure; require specific disclosure against specific warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete \"discoverable\" — only **actual knowledge** of named deal-team individuals, not constructive/imputed knowledge and not advisers' knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Actual Bluefen consent (and satisfaction of 11.3 conditions) as a **Condition Precedent to Completion**"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Repayment and **discharge of security as a Completion deliverable/condition**"
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Either the Seller pays at Completion, or the full amount **plus on-costs** is a defined Leakage / price deduction in the funds flow."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A broad IP indemnity covering **loss of/failure to vest the IP**, not just the AUD 180k fee."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "A **specific indemnity** for all costs/liabilities arising from the incident"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Diligence on terminability/commitment; if these are new committed spend, reflect in price or warrant as ordinary course."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Reverse the presumption — fundamental warranties, tax, specific indemnities and **fraud/wilful concealment** are **excluded** from all limitations unless expressly stated."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Independent verification (ASIC search, share certificates, prior transfer chain)"
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "fundamental warranties, tax, specific indemnities and **fraud/wilful concealment** are **excluded** from all limitations unless expressly stated."
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "A 20% general cap is within market range for a deal this size",
  "names_manipulation": false
}

